package com.mplad.fraud_detection.entity;
import java.time.LocalDateTime; import jakarta.persistence.*;
@Entity @Table(name="contractor_notifications") public class ContractorNotification { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="contractor_id",nullable=false) private String contractorId; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="project_id",nullable=false) private Project project; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="review_id",nullable=false) private AuthorityReview review; @Column(nullable=false) private String title; @Column(nullable=false,length=1500) private String message; @Column(name="notification_type",nullable=false) private String notificationType; @Column(name="is_read",nullable=false) private boolean read; @Column(name="created_at",nullable=false) private LocalDateTime createdAt; public Long getId(){return id;} public String getContractorId(){return contractorId;} public Project getProject(){return project;} public AuthorityReview getReview(){return review;} public String getTitle(){return title;} public String getMessage(){return message;} public boolean isRead(){return read;} public LocalDateTime getCreatedAt(){return createdAt;} public void setContractorId(String v){contractorId=v;} public void setProject(Project v){project=v;} public void setReview(AuthorityReview v){review=v;} public void setTitle(String v){title=v;} public void setMessage(String v){message=v;} public void setNotificationType(String v){notificationType=v;} public void setRead(boolean v){read=v;} public void setCreatedAt(LocalDateTime v){createdAt=v;} }
